use std::fs
use std::collections::HashMap

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut acc: HashMap<string, int> = HashMap::new()
    for line in text.lines() {
        let p: Vec<string> = line.split_whitespace().collect()
        if p.len() == 0 {
            continue
        }
        let cmd = p[0]
        if cmd == "open" && p.len() >= 3 {
            let name = p[1]
            let amt: int = p[2].parse::<int>().unwrap_or(0)
            if amt < 0 {
                println("error: invalid amount")
            } else if acc.contains_key(name) {
                println("error: duplicate account")
            } else {
                acc.insert(name, amt)
                println("ok")
            }
        } else if (cmd == "deposit" || cmd == "withdraw") && p.len() >= 3 {
            let name = p[1]
            let amt: int = p[2].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(name) {
                println("error: unknown account ${name}")
            } else {
                let bal: int = acc.get(name).unwrap_or(0)
                if cmd == "deposit" {
                    acc.insert(name, bal + amt)
                    println("ok")
                } else if bal < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(name, bal - amt)
                    println("ok")
                }
            }
        } else if cmd == "transfer" && p.len() >= 4 {
            let a = p[1]
            let b = p[2]
            let amt: int = p[3].parse::<int>().unwrap_or(0)
            if amt <= 0 {
                println("error: invalid amount")
            } else if !acc.contains_key(a) {
                println("error: unknown account ${a}")
            } else if !acc.contains_key(b) {
                println("error: unknown account ${b}")
            } else if a == b {
                println("error: same account")
            } else {
                let ba: int = acc.get(a).unwrap_or(0)
                let bb: int = acc.get(b).unwrap_or(0)
                if ba < amt {
                    println("error: insufficient funds")
                } else {
                    acc.insert(a, ba - amt)
                    acc.insert(b, bb + amt)
                    println("ok")
                }
            }
        } else if cmd == "balance" && p.len() >= 2 {
            let name = p[1]
            if !acc.contains_key(name) {
                println("error: unknown account ${name}")
            } else {
                let bal: int = acc.get(name).unwrap_or(0)
                println("${bal}")
            }
        }
    }
    let mut keys: Vec<string> = []
    for k in acc.keys() {
        keys.push(k)
    }
    keys.sort()
    for k in keys {
        let v: int = acc.get(k).unwrap_or(0)
        println("${k} ${v}")
    }
}

